     2→ * LATECME Application JavaScript
     3→ * Global configuration for HTMX and Alpine.js
     4→ */
     5→
     6→// =============================================================================
     7→// HTMX Configuration
     8→// =============================================================================
     9→
    10→// Configure HTMX to include CSRF token in all requests
    11→document.addEventListener('DOMContentLoaded', function() {
    12→    // Get CSRF token from cookie
    13→    function getCookie(name) {
    14→        let cookieValue = null;
    15→        if (document.cookie && document.cookie !== '') {
    16→            const cookies = document.cookie.split(';');
    17→            for (let i = 0; i < cookies.length; i++) {
    18→                const cookie = cookies[i].trim();
    19→                if (cookie.substring(0, name.length + 1) === (name + '=')) {
    20→                    cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
    21→                    break;
    22→                }
    23→            }
    24→        }
    25→        return cookieValue;
    26→    }
    27→
    28→    const csrftoken = getCookie('csrftoken');
    29→
    30→    // Add CSRF token to all HTMX requests
    31→    document.body.addEventListener('htmx:configRequest', function(event) {
    32→        event.detail.headers['X-CSRFToken'] = csrftoken;
    33→    });
    34→
    35→    // Handle HTMX errors
    36→    document.body.addEventListener('htmx:responseError', function(event) {
    37→        console.error('HTMX Error:', event.detail);
    38→        // You could show a toast notification here
    39→    });
    40→
    41→    // Add loading class to body during HTMX requests
    42→    document.body.addEventListener('htmx:beforeRequest', function(event) {
    43→        const indicator = event.detail.elt.querySelector('.htmx-indicator');
    44→        if (indicator) {
    45→            indicator.style.display = 'inline-block';
    46→        }
    47→    });
    48→
    49→    document.body.addEventListener('htmx:afterRequest', function(event) {
    50→        const indicator = event.detail.elt.querySelector('.htmx-indicator');
    51→        if (indicator) {
    52→            indicator.style.display = 'none';
    53→        }
    54→    });
    55→
    56→    // Handle HTMX redirect responses (for Django login required)
    57→    document.body.addEventListener('htmx:beforeSwap', function(event) {
    58→        // Check if response is a redirect to login page
    59→        if (event.detail.xhr.status === 403 || event.detail.xhr.status === 401) {
    60→            window.location.href = '/accounts/login/';
    61→        }
    62→    });
    63→});
    64→
    65→// =============================================================================
    66→// Alpine.js Global Data and Utilities
    67→// =============================================================================
    68→
    69→// Register Alpine.js global stores when Alpine is ready
    70→document.addEventListener('alpine:init', () => {
    71→    // Toast notification store
    72→    Alpine.store('toasts', {
    73→        items: [],
    74→
    75→        add(message, type = 'info', duration = 5000) {
    76→            const id = Date.now();
    77→            this.items.push({ id, message, type });
    78→
    79→            if (duration > 0) {
    80→                setTimeout(() => this.remove(id), duration);
    81→            }
    82→        },
    83→
    84→        remove(id) {
    85→            this.items = this.items.filter(item => item.id !== id);
    86→        },
    87→
    88→        success(message) {
    89→            this.add(message, 'success');
    90→        },
    91→
    92→        error(message) {
    93→            this.add(message, 'danger');
    94→        },
    95→
    96→        warning(message) {
    97→            this.add(message, 'warning');
    98→        },
    99→
   100→        info(message) {
   101→            this.add(message, 'info');
   102→        }
   103→    });
   104→
   105→    // Sidebar state store
   106→    Alpine.store('sidebar', {
   107→        open: false,
   108→
   109→        toggle() {
   110→            this.open = !this.open;
   111→        },
   112→
   113→        close() {
   114→            this.open = false;
   115→        }
   116→    });
   117→
   118→    // Global modal helper
   119→    Alpine.data('modal', (initialOpen = false) => ({
   120→        open: initialOpen,
   121→
   122→        show() {
   123→            this.open = true;
   124→            document.body.classList.add('modal-open');
   125→        },
   126→
   127→        hide() {
   128→            this.open = false;
   129→            document.body.classList.remove('modal-open');
   130→        },
   131→
   132→        toggle() {
   133→            this.open ? this.hide() : this.show();
   134→        }
   135→    }));
   136→
   137→    // Dropdown helper
   138→    Alpine.data('dropdown', () => ({
   139→        open: false,
   140→
   141→        toggle() {
   142→            this.open = !this.open;
   143→        },
   144→
   145→        close() {
   146→            this.open = false;
   147→        }
   148→    }));
   149→
   150→    // Confirm dialog helper
   151→    Alpine.data('confirmDialog', () => ({
   152→        open: false,
   153→        title: '',
   154→        message: '',
   155→        confirmText: 'Confirmar',
   156→        cancelText: 'Cancelar',
   157→        onConfirm: null,
   158→
   159→        show(options = {}) {
   160→            this.title = options.title || 'Confirmar';
   161→            this.message = options.message || 'Tem certeza?';
   162→            this.confirmText = options.confirmText || 'Confirmar';
   163→            this.cancelText = options.cancelText || 'Cancelar';
   164→            this.onConfirm = options.onConfirm || null;
   165→            this.open = true;
   166→        },
   167→
   168→        confirm() {
   169→            if (typeof this.onConfirm === 'function') {
   170→                this.onConfirm();
   171→            }
   172→            this.open = false;
   173→        },
   174→
   175→        cancel() {
   176→            this.open = false;
   177→        }
   178→    }));
   179→});
   180→
   181→// =============================================================================
   182→// Utility Functions
   183→// =============================================================================
   184→
   185→// Format currency (Brazilian Real)
   186→function formatCurrency(value) {
   187→    return new Intl.NumberFormat('pt-BR', {
   188→        style: 'currency',
   189→        currency: 'BRL'
   190→    }).format(value);
   191→}
   192→
   193→// Format date (Brazilian format)
   194→function formatDate(dateString) {
   195→    const date = new Date(dateString);
   196→    return new Intl.DateTimeFormat('pt-BR').format(date);
   197→}
   198→
   199→// Format datetime (Brazilian format)
   200→function formatDateTime(dateString) {
   201→    const date = new Date(dateString);
   202→    return new Intl.DateTimeFormat('pt-BR', {
   203→        dateStyle: 'short',
   204→        timeStyle: 'short'
   205→    }).format(date);
   206→}
   207→
   208→// Debounce function for search inputs
   209→function debounce(func, wait) {
   210→    let timeout;
   211→    return function executedFunction(...args) {
   212→        const later = () => {
   213→            clearTimeout(timeout);
   214→            func(...args);
   215→        };
   216→        clearTimeout(timeout);
   217→        timeout = setTimeout(later, wait);
   218→    };
   219→}
   220→
   221→// =============================================================================
   222→// HTMX Extensions
   223→// =============================================================================
   224→
   225→// Custom HTMX extension for handling Django messages
   226→htmx.defineExtension('django-messages', {
   227→    onEvent: function(name, evt) {
   228→        if (name === 'htmx:afterSwap') {
   229→            // Look for messages in the response
   230→            const messagesContainer = evt.detail.elt.querySelector('[data-messages]');
   231→            if (messagesContainer && window.Alpine) {
   232→                const messages = JSON.parse(messagesContainer.dataset.messages || '[]');
   233→                messages.forEach(msg => {
   234→                    Alpine.store('toasts').add(msg.message, msg.tags);
   235→                });
   236→            }
   237→        }
   238→    }
   239→});
   240→
   241→// =============================================================================
   242→// Icon Helper
   243→// =============================================================================
   244→
   245→// Function to use Tabler icons from sprite
   246→function icon(name, size = 24, strokeWidth = 2) {
   247→    return `<svg class="icon icon-tabler" width="${size}" height="${size}" viewBox="0 0 24 24" stroke-width="${strokeWidth}" stroke="currentColor" fill="none" stroke-linecap="round" stroke-linejoin="round">
   248→        <use href="/static/icons/tabler-sprite.svg#tabler-${name}"></use>
   249→    </svg>`;
   250→}
